css:
.sym{display:grid;gap:1px;background:var(--glass-border);border:1px solid var(--glass-border);
      border-radius:var(--radius-lg);overflow:hidden}
    .sym div{background:var(--glass);padding:13px 16px;color:var(--ink-2);font-size:.95rem}
    .sym div b{color:var(--ink);font-weight:600}
    .honest{background:var(--accent-soft);border:1px solid rgba(47,212,194,.25);
      border-radius:var(--radius-lg);padding:clamp(18px,3vw,26px)}
    .honest h3{font-family:var(--display);font-size:1.05rem;margin:0 0 10px;color:var(--ink)}
    .honest ul{margin:0;padding-left:1.1rem;color:var(--ink-2);font-size:.95rem}
    .honest li{margin-bottom:.55rem}
    .honest li b{color:var(--ink)}
    .area{font-family:var(--mono);font-size:.8rem;color:var(--ink-2);line-height:2.1}
    .area b{color:var(--accent);font-weight:500}

    /* FAQ — same treatment as the homepage */
    .fv-faq details{background:var(--glass);border:1px solid var(--glass-border);color:var(--ink-2);
      border-radius:var(--radius);padding:14px 18px;margin-bottom:12px;backdrop-filter:var(--blur);
      -webkit-backdrop-filter:var(--blur);box-shadow:inset 0 1px 0 rgba(255,255,255,.06);
      transition:background .2s ease,border-color .2s ease}
    .fv-faq details:hover{background:var(--glass-2);border-color:var(--glass-border-2)}
    .fv-faq summary::-webkit-details-marker{display:none}
    .fv-faq summary::marker{content:""}
    .fv-faq summary{cursor:pointer;font-family:var(--display);font-weight:700;font-size:1.02rem;
      color:var(--ink);outline:none;list-style:none;position:relative;padding-right:28px}
    .fv-faq summary::after{content:"+";position:absolute;right:0;top:0;font-size:1.2rem;font-weight:700;
      color:var(--accent);transition:transform .2s ease,opacity .2s ease;opacity:.9}
    .fv-faq details[open] summary::after{content:"–";transform:rotate(180deg)}
    .fv-faq details p{margin:10px 0 0;color:var(--ink-2);font-size:.95rem;line-height:1.5}
